update pages set contenu = '{"gabarit":"editorial","chapeau":"Un prestataire de maintenance se choisit sur des visages et des engagements, pas sur une plaquette. Cette page prolonge la présentation de [migen service](/nous-connaitre/) : qui fait quoi, qui vous répond, et comment ces personnes sont choisies.","blocs":[]}'::jsonb where path = '/a-propos/equipe/';
update pages set contenu = jsonb_set(contenu, '{blocs}', (contenu->'blocs') || '[{"type":"citation","texte":"Pour joindre directement l''équipe : 04 78 33 72 05, du lundi au vendredi de 8h00 à 18h30."},{"type":"titre","niveau":2,"texte":"Qui nous sommes","id":"qui-nous-sommes"},{"type":"paragraphe","texte":"Une entreprise de maintenance industrielle créée pour une chose : garder vos machines en marche, partout en France."},{"type":"liste","items":[{"accroche":"2021","texte":"Année de création · Fondée par Nathan Jorez, l''entreprise pilote son activité depuis Limonest, avec des bureaux à Écully."},{"accroche":"+100","texte":"Collaborateurs · Techniciens, chargés d''affaires, référents techniques et fonctions support, répartis sur quatre agences."},{"accroche":"+120","texte":"Clients accompagnés · Dont plus de 80 réguliers, de la PME à l''industrie lourde, en France entière."}]},{"type":"titre","niveau":2,"texte":"Notre histoire","id":"notre-histoire"},{"type":"paragraphe","texte":"Une trajectoire courte et dense : chaque étape a ajouté une brique au service, jamais une couche de complexité."},{"type":"liste","items":[{"accroche":"2021, la création","texte":"Nathan Jorez fonde Migen à Lyon avec une conviction : la maintenance se juge sur l''état des lignes, pas sur les promesses."},{"accroche":"La construction du réseau","texte":"Quatre agences ouvrent pour suivre les clients là où sont leurs usines : Lyon (siège), Montréal, Dubaï, Madrid."}],"ordonnee":true},{"type":"paragraphe","texte":"3."},{"type":"liste","items":[{"accroche":"Aujourd''hui","texte":"Plus de 100 collaborateurs, plus de 120 clients accompagnés, et une exigence de recrutement inchangée : 10 % des candidats retenus."}],"ordonnee":true},{"type":"titre","niveau":2,"texte":"Nos équipes, rôle par rôle","id":"nos-equipes-role-par-role"},{"type":"paragraphe","texte":"Pas d''organigramme décoratif : quatre rôles, quatre responsabilités, et un principe : vous savez toujours qui porte quoi."},{"type":"liste","items":[{"accroche":"Le chargé d''affaires","texte":"Votre premier contact. Il qualifie la demande, écrit le périmètre, chiffre, puis suit la mission. C''est lui qui vous rappelle dans l''heure."},{"accroche":"Le référent technique","texte":"Il encadre les techniciens, contrôle la qualité des interventions et suit la progression de chacun. Vous ne managez pas un métier qui n''est pas le vôtre."},{"accroche":"Les techniciens de terrain","texte":"Mécaniciens, électriciens, électromécaniciens : ceux qui diagnostiquent, réparent et documentent chaque opération dans votre GMAO."},{"accroche":"Les spécialistes du groupe","texte":"Automaticiens SIEMENS et Schneider, roboticiens ABB et Fanuc. Ils interviennent en renfort : aucun technicien n''est seul face à une panne complexe."}]},{"type":"titre","niveau":2,"texte":"Comment ces personnes sont choisies","id":"comment-ces-personnes-sont-choisies"},{"type":"paragraphe","texte":"La qualité d''une intervention se décide au recrutement, bien avant l''arrivée sur votre site. Notre sélection tient en trois étapes, et en un chiffre : 10 % des candidats sont retenus."},{"type":"liste","items":[{"accroche":"L''entretien technique","texte":"Chaque candidat est évalué sur des cas réels de son métier : diagnostic, méthode, gestes de sécurité. Pas de recrutement sur CV seul."},{"accroche":"L''entretien comportemental","texte":"Un technicien travaille chez vous, avec vos équipes : posture, communication et fiabilité pèsent autant que la technique."},{"accroche":"Les résultats partagés","texte":"Pour un poste en résidence, les résultats d''évaluation vous sont présentés avant votre décision. Vous validez, ou nous cherchons encore."}],"ordonnee":true},{"type":"titre","niveau":2,"texte":"Nos implantations","id":"nos-implantations"},{"type":"paragraphe","texte":"Quatre agences portent le réseau, des hubs de techniciens dans les grandes villes rapprochent les équipes des usines. Le détail par bassin est sur nos pages [maintenance industrielle france](/implantations/)."},{"type":"tableau","entetes":["Agence","Territoire couvert"],"lignes":[["Lyon, le siège","Auvergne-Rhône-Alpes, depuis Limonest et Écully"],["Paris","Île-de-France et Bassin parisien"],["Strasbourg","Alsace et Grand Est"],["Nantes","Grand Ouest"],["Toulouse","Occitanie et Nouvelle-Aquitaine"]]},{"type":"titre","niveau":2,"texte":"Nos engagements","id":"nos-engagements"},{"type":"paragraphe","texte":"Pas de mur de certifications en page d''accueil : des engagements tenus, vérifiables mission après mission."},{"type":"liste","items":[{"accroche":"Rappel dans l''heure","texte":"Toute demande reçue du lundi au vendredi, de 8h00 à 18h30, est rappelée dans l''heure par un chargé d''affaires."},{"accroche":"Astreinte 24/24 et 7/7","texte":"En option, pour couvrir les nuits, les week-ends et les jours fériés, avec un circuit d''appel écrit."},{"accroche":"Transparence complète","texte":"Périmètre écrit, pièces au prix réel du marché, comptes rendus dans votre GMAO. Nos [études de cas](/preuves/) sont documentées et vérifiables."}]},{"type":"titre","niveau":2,"texte":"Questions fréquentes","id":"questions-frequentes"},{"type":"paragraphe","texte":"Vous ne voyez jamais un technicien seul face à un imprévu qui dépasse son métier : voici comment l''équipe s''organise autour de lui."}]'::jsonb) where path = '/a-propos/equipe/';
update pages set contenu = jsonb_set(contenu, '{blocs}', (contenu->'blocs') || '[{"type":"liste","items":[{"accroche":"Qui est mon interlocuteur au quotidien ?","texte":"Le chargé d''affaires. Il qualifie votre demande, chiffre la mission, puis la suit jusqu''à la fin : un seul point de contact, du premier appel au compte rendu."},{"accroche":"Le technicien qui intervient sur mon site est-il seul décideur ?","texte":"Non. Le référent technique encadre chaque intervention et contrôle la qualité. Sur une panne complexe, les spécialistes du groupe, automaticiens ou roboticiens, viennent en renfort."},{"accroche":"Comment savoir si un technicien est fiable avant qu''il arrive chez moi ?","texte":"Il a passé un entretien technique sur des cas réels, puis un entretien comportemental. Seuls 10 % des candidats sont retenus."},{"accroche":"Pour un poste en résidence, ai-je mon mot à dire sur le choix du technicien ?","texte":"Oui. Les résultats de son évaluation vous sont présentés avant votre décision. Vous validez, ou nous cherchons encore."},{"accroche":"Le hub de techniciens le plus proche de mon site est-elle la seule à pouvoir intervenir ?","texte":"Non. Les quatre agences et leurs hubs techniques mobilisent la compétence disponible sur tout le territoire, pas seulement l''agence locale."},{"accroche":"Comment vous contacter directement ?","texte":"Au 04 78 33 72 05, du lundi au vendredi de 8h00 à 18h30. Votre demande est rappelée dans l''heure par un chargé d''affaires."}]},{"type":"citation","texte":"[Demander un devis](/contact/)"}]'::jsonb) where path = '/a-propos/equipe/';
